export const NOTES = [{"date": "01-01", "month": "January", "day": 1, "text": "Grief doesn't check a calendar. Some days it just hurts more, no reason needed. That doesn't mean you're moving backward.", "kind": "reflection"}, {"date": "01-02", "month": "January", "day": 2, "text": "Don't stop talking to them when you need to tell them something. Tell them out loud or in silence, tell them with your heart. They're still listening, in whatever way that means now.", "kind": "ritual"}, {"date": "01-03", "month": "January", "day": 3, "text": "Grief doesn't go quiet — it's still fizzing under the surface, even on the calm days. It doesn't have to be pouring out to be real.", "kind": "reflection"}, {"date": "01-04", "month": "January", "day": 4, "text": "A stranger laughed like they did once, and for half a second your whole chest lifted. That flicker of joy was real — let it stay, even briefly.", "kind": "reflection"}, {"date": "01-05", "month": "January", "day": 5, "text": "You don't have to perform being okay. And when you're ready to feel okay for real, that's allowed too.", "kind": "reflection"}, {"date": "01-06", "month": "January", "day": 6, "text": "The little things they used to say are still in your head, in their voice. That voice isn't gone — you carry it now.", "kind": "reflection"}, {"date": "01-07", "month": "January", "day": 7, "text": "Some days grief is loud. Others it's barely there. Both are signs you're still moving through this, not stuck in it.", "kind": "reflection"}, {"date": "01-08", "month": "January", "day": 8, "text": "Grief doesn't always look like tears — sometimes it's just tired, for no obvious reason. Rest is allowed. It's not giving up.", "kind": "reflection"}, {"date": "01-09", "month": "January", "day": 9, "text": "You're allowed to laugh at something without it meaning your grief is any smaller. Joy and grief share space more often than people admit.", "kind": "reflection"}, {"date": "01-10", "month": "January", "day": 10, "text": "Carrying on isn't the same as being fine. But carrying on, even slowly, means something in you is still choosing to keep going.", "kind": "reflection"}, {"date": "01-11", "month": "January", "day": 11, "text": "Grief isn't something to get through. It's something you learn to carry, one ordinary moment at a time.", "kind": "reflection"}, {"date": "01-12", "month": "January", "day": 12, "text": "You don't need a reason to think of them. They don't need an occasion to be missed.", "kind": "reflection"}, {"date": "01-13", "month": "January", "day": 13, "text": "Some songs still stop you mid-step. Let them. That's not a setback — that's love with nowhere else to go but out.", "kind": "reflection"}, {"date": "01-14", "month": "January", "day": 14, "text": "Cook one of their favourite meals. Taste it the way they would have, and let that be enough.", "kind": "ritual"}, {"date": "01-15", "month": "January", "day": 15, "text": "Grief and gratitude aren't opposites. You can wish they were here and still be thankful they were, in the very same breath.", "kind": "reflection"}, {"date": "01-16", "month": "January", "day": 16, "text": "Nobody grieves \"correctly.\" However this looks for you, it's exactly how it's supposed to look.", "kind": "reflection"}, {"date": "01-17", "month": "January", "day": 17, "text": "Write them a letter — the things left unsaid, the small updates, the ordinary stuff. Seal it or don't. It still counts.", "kind": "ritual"}, {"date": "01-18", "month": "January", "day": 18, "text": "Some days you'll speak of them easily. Other days their name will catch in your throat. Both are still you, loving them.", "kind": "reflection"}, {"date": "01-19", "month": "January", "day": 19, "text": "The world kept turning. That was never a betrayal — it just means there's still a place in it for you to keep loving them from.", "kind": "reflection"}, {"date": "01-20", "month": "January", "day": 20, "text": "Grief doesn't mean you're stuck. It means something mattered enough to still be felt, long after.", "kind": "reflection"}, {"date": "01-21", "month": "January", "day": 21, "text": "You're allowed to build a new life without it meaning you're leaving them behind. They're not a chapter you closed. They're part of every page after.", "kind": "reflection"}, {"date": "01-22", "month": "January", "day": 22, "text": "Sit somewhere they loved. You don't have to say anything. Just let the quiet be shared.", "kind": "ritual"}, {"date": "01-23", "month": "January", "day": 23, "text": "Some days grief feels like a weight. Other days, oddly, like a warmth. Neither one is wrong.", "kind": "reflection"}, {"date": "01-24", "month": "January", "day": 24, "text": "You are allowed to want good things for yourself. Wanting joy isn't wanting them any less.", "kind": "reflection"}, {"date": "01-25", "month": "January", "day": 25, "text": "Look through old photos of them, not to ache, but to remember how loved you were, and still are.", "kind": "ritual"}, {"date": "01-26", "month": "January", "day": 26, "text": "Grief doesn't erase the good years. It's proof there were good years worth grieving.", "kind": "reflection"}, {"date": "01-27", "month": "January", "day": 27, "text": "You don't owe anyone a timeline for this. Not even yourself.", "kind": "reflection"}, {"date": "01-28", "month": "January", "day": 28, "text": "Say their name out loud, to someone, or just to the room. It keeps them present, not past.", "kind": "ritual"}, {"date": "01-29", "month": "January", "day": 29, "text": "Some days you'll feel closer to them than others. That's not you failing to hold on — that's just how love breathes.", "kind": "reflection"}, {"date": "01-30", "month": "January", "day": 30, "text": "Grief is proof of a bond nothing could undo, not even this. That's not a small thing. That's everything.", "kind": "reflection"}, {"date": "01-31", "month": "January", "day": 31, "text": "Some days call for a sad song, the one that's unmistakably them. Let it play. Let yourself cry. It's not wallowing — it's letting love move through you.", "kind": "reflection"}, {"date": "02-01", "month": "February", "day": 1, "text": "You'll catch yourself doing something they used to do — a phrase, a gesture, a look. That's not a coincidence. That's them, still living on in you.", "kind": "reflection"}, {"date": "02-02", "month": "February", "day": 2, "text": "If they visit you in a dream, even a strange or hard one, say thank you when you wake. However brief, it was still a visit.", "kind": "reflection"}, {"date": "02-03", "month": "February", "day": 3, "text": "Grief has no finish line to cross. There's no version of this where you're suddenly \"done.\" And that's alright — because that would mean the love was done too.", "kind": "reflection"}, {"date": "02-04", "month": "February", "day": 4, "text": "You don't have to explain your grief to people who've never carried it. Save your energy for the ones who understand without asking.", "kind": "reflection"}, {"date": "02-05", "month": "February", "day": 5, "text": "The ache and the love are the same size. That's not a curse — that's just how much they mattered.", "kind": "reflection"}, {"date": "02-06", "month": "February", "day": 6, "text": "Some memories will make you smile before they make you ache. Let the smile come first, for once.", "kind": "reflection"}, {"date": "02-07", "month": "February", "day": 7, "text": "You're not \"moving on.\" You're moving forward, with them folded into who you're becoming.", "kind": "reflection"}, {"date": "02-08", "month": "February", "day": 8, "text": "Talk to them while you cook, while you drive, while you're doing nothing at all. You don't need a reason. You never did.", "kind": "ritual"}, {"date": "02-09", "month": "February", "day": 9, "text": "However far time takes you from that day, it will never take you further from them.", "kind": "reflection"}, {"date": "02-10", "month": "February", "day": 10, "text": "Losing them was like walking through a veil. The world looks the same on the other side — it just isn't, not anymore.", "kind": "reflection"}, {"date": "02-11", "month": "February", "day": 11, "text": "You're not seeing the world wrong now. You're just seeing it as someone who knows what can be lost.", "kind": "reflection"}, {"date": "02-12", "month": "February", "day": 12, "text": "Let yourself want something new without guilt. Wanting things is still allowed. You're still allowed.", "kind": "reflection"}, {"date": "02-13", "month": "February", "day": 13, "text": "Some people will expect you to be \"over it\" by now. You don't owe them a performance. You owe yourself honesty.", "kind": "reflection"}, {"date": "02-14", "month": "February", "day": 14, "text": "Love doesn't stop needing somewhere to go just because they're gone. Let it go into remembering, into others, into you.", "kind": "reflection"}, {"date": "02-15", "month": "February", "day": 15, "text": "Play their favourite song, loud enough to fill the room. Let it feel like they're filling it too.", "kind": "ritual"}, {"date": "02-16", "month": "February", "day": 16, "text": "Grief will ambush you in ordinary places — a supermarket aisle, a smell, a stranger's coat. Let it. You don't have to brace for it constantly.", "kind": "reflection"}, {"date": "02-17", "month": "February", "day": 17, "text": "You are allowed to talk about them in present tense sometimes. Love isn't only past tense just because they are.", "kind": "reflection"}, {"date": "02-18", "month": "February", "day": 18, "text": "The version of you that hasn't lost them doesn't exist anymore. But the version of you that loved them fiercely enough to still ache — that one's still here, and still worth being.", "kind": "reflection"}, {"date": "02-19", "month": "February", "day": 19, "text": "However heavy the day feels, you have survived every hard day so far. That's not nothing. That's everything.", "kind": "reflection"}, {"date": "02-20", "month": "February", "day": 20, "text": "Spray their perfume, just to breathe them in for a second. Some things don't need words — scent remembers what nothing else can.", "kind": "ritual"}, {"date": "02-21", "month": "February", "day": 21, "text": "Hug a pillow and let yourself imagine they're holding you back. It's not silly. It's just love, looking for somewhere to land.", "kind": "ritual"}, {"date": "02-22", "month": "February", "day": 22, "text": "You don't have to be strong for anyone. Not even for yourself.", "kind": "reflection"}, {"date": "02-23", "month": "February", "day": 23, "text": "The relationship didn't end. It just changed shape — from presence to memory, from conversation to feeling.", "kind": "reflection"}, {"date": "02-24", "month": "February", "day": 24, "text": "Notice the small ways you've grown since losing them. Grief and growth aren't opposites, however unfair that feels.", "kind": "ritual"}, {"date": "02-25", "month": "February", "day": 25, "text": "You're allowed to be angry — at the unfairness, the timing, even at them for leaving. Anger is love with nowhere to put itself.", "kind": "reflection"}, {"date": "02-26", "month": "February", "day": 26, "text": "Keep something of theirs close by — a jumper, a mug, a note. It's not holding on too tightly. It's just holding on.", "kind": "ritual"}, {"date": "02-27", "month": "February", "day": 27, "text": "Some anniversaries ache more than others, and some ordinary Tuesdays surprise you. There's no predicting grief, and you don't have to try.", "kind": "reflection"}, {"date": "02-28", "month": "February", "day": 28, "text": "You will always be someone who loved them. That never expires, no matter how much time passes.", "kind": "reflection"}, {"date": "02-29", "month": "February", "day": 29, "text": "Forgive yourself for the days you didn't think of them. Love isn't measured in constant thought — it's measured in how deeply it's rooted.", "kind": "reflection"}, {"date": "03-01", "month": "March", "day": 1, "text": "Grief isn't a problem to solve. It's a love story that's still being written, just in a different tense now.", "kind": "reflection"}, {"date": "03-02", "month": "March", "day": 2, "text": "Drive somewhere with no destination, just to think of them. Let the road hold the quiet with you.", "kind": "reflection"}, {"date": "03-03", "month": "March", "day": 3, "text": "You're not betraying them by finding moments of happiness. Their love didn't come with conditions, and neither does yours.", "kind": "reflection"}, {"date": "03-04", "month": "March", "day": 4, "text": "Some days you'll feel closer to the person you were before. Other days, closer to who you've become since. Both are still you.", "kind": "reflection"}, {"date": "03-05", "month": "March", "day": 5, "text": "Light a candle for them, wait for them, whenever it feels right. No occasion needed, just the wanting to.", "kind": "ritual"}, {"date": "03-06", "month": "March", "day": 6, "text": "Tell someone a story about them. Keep them part of the conversation, not just the memory.", "kind": "reflection"}, {"date": "03-07", "month": "March", "day": 7, "text": "Grief will soften in places and sharpen in others. It was never going to move in a straight line, and it was never meant to.", "kind": "reflection"}, {"date": "03-08", "month": "March", "day": 8, "text": "You don't have to hold it together for other people's comfort. Let them witness the real thing.", "kind": "reflection"}, {"date": "03-09", "month": "March", "day": 9, "text": "Notice a habit or phrase of theirs living on in you. That's not haunting. That's inheritance.", "kind": "ritual"}, {"date": "03-10", "month": "March", "day": 10, "text": "However this day unfolds, you are still someone who loved deeply enough to still be grieving. That's not a flaw. That's proof of the love.", "kind": "reflection"}, {"date": "03-11", "month": "March", "day": 11, "text": "You can love your life now and still wish they were in it. Neither feeling cancels the other out.", "kind": "reflection"}, {"date": "03-12", "month": "March", "day": 12, "text": "Grief has taught you things happiness never could — patience with yourself, tenderness for others who are hurting, and how much you're capable of surviving.", "kind": "reflection"}, {"date": "03-13", "month": "March", "day": 13, "text": "Sit in the sun and just breathe, without needing it to mean anything. Rest doesn't require justification.", "kind": "ritual"}, {"date": "03-14", "month": "March", "day": 14, "text": "Write down a memory you're scared of forgetting. Not because you will — because it deserves to be kept somewhere solid.", "kind": "ritual"}, {"date": "03-15", "month": "March", "day": 15, "text": "You don't need to be the strong one in every room. Let someone else hold space for you, for once.", "kind": "reflection"}, {"date": "03-16", "month": "March", "day": 16, "text": "Their absence is loud sometimes. Let it be. It's just love, echoing.", "kind": "reflection"}, {"date": "03-17", "month": "March", "day": 17, "text": "Notice the people who still ask how you're really doing, long after everyone else stopped asking. Let them in.", "kind": "ritual"}, {"date": "03-18", "month": "March", "day": 18, "text": "You are not \"too much\" for grieving this deeply, for this long. Love this size doesn't come with an expiry date.", "kind": "reflection"}, {"date": "03-19", "month": "March", "day": 19, "text": "Look in the mirror and find them in your face, your gestures, your laugh. You're not just missing them — you're carrying them forward.", "kind": "ritual"}, {"date": "03-20", "month": "March", "day": 20, "text": "Grief is love that ran out of tomorrow. It never runs out of the days you're still living.", "kind": "reflection"}, {"date": "03-21", "month": "March", "day": 21, "text": "You're allowed to leave a space empty at the table sometimes, and other times fill it with someone new. Either way honours them.", "kind": "reflection"}, {"date": "03-22", "month": "March", "day": 22, "text": "Grief doesn't ask permission to visit. Let it in, sit with it a while, and let it leave in its own time.", "kind": "reflection"}, {"date": "03-23", "month": "March", "day": 23, "text": "Say something out loud you never got to tell them. It's never too late for a conversation like that.", "kind": "ritual"}, {"date": "03-24", "month": "March", "day": 24, "text": "You survived the version of this that felt unsurvivable. Everything since has been proof you're stronger than that day gave you credit for.", "kind": "reflection"}, {"date": "03-25", "month": "March", "day": 25, "text": "Wear something of theirs. Let it feel like a small embrace, worn close to the skin.", "kind": "ritual"}, {"date": "03-26", "month": "March", "day": 26, "text": "Grief doesn't mean you loved them more than someone who grieves quietly. Love just wears different faces in different people.", "kind": "reflection"}, {"date": "03-27", "month": "March", "day": 27, "text": "You don't have to justify why you're crying at something small. Grief doesn't always pick a big enough reason.", "kind": "reflection"}, {"date": "03-28", "month": "March", "day": 28, "text": "Look at the sky for a moment, and let yourself wonder if any part of them is out there, still watching over you.", "kind": "ritual"}, {"date": "03-29", "month": "March", "day": 29, "text": "You're not broken for still hurting this long after. You're just someone who loved deeply, in a world that expects grief to have a deadline.", "kind": "reflection"}, {"date": "03-30", "month": "March", "day": 30, "text": "Plant something in their memory. Watch it grow the way your love for them still does.", "kind": "ritual"}, {"date": "03-31", "month": "March", "day": 31, "text": "Some days the ache feels unbearable. It always has passed before. It will again.", "kind": "reflection"}, {"date": "04-01", "month": "April", "day": 1, "text": "Grief and love are not stages you move through — they're companions that walk beside you, at different distances, for as long as you need them to.", "kind": "reflection"}, {"date": "04-02", "month": "April", "day": 2, "text": "You are allowed to be both okay and not okay in the very same hour. Grief was never simple enough to pick just one.", "kind": "reflection"}, {"date": "04-03", "month": "April", "day": 3, "text": "Look through their handwriting if you have it — a note, a card, a list. Let their hand feel close to yours again for a moment.", "kind": "ritual"}, {"date": "04-04", "month": "April", "day": 4, "text": "You're not losing them further with every passing year. You're just finding new ways to keep them close.", "kind": "reflection"}, {"date": "04-05", "month": "April", "day": 5, "text": "Grief will still catch you off guard, even years from now. That's not a setback. That's just how deeply this runs.", "kind": "reflection"}, {"date": "04-06", "month": "April", "day": 6, "text": "Cook enough for two, some evenings, just for the comfort of the habit. You don't have to explain it to anyone.", "kind": "ritual"}, {"date": "04-07", "month": "April", "day": 7, "text": "You're allowed to feel relief on hard days too — relief that the pain isn't as sharp as it once was. That's not forgetting. That's healing, quietly doing its work.", "kind": "reflection"}, {"date": "04-08", "month": "April", "day": 8, "text": "Notice the small kindnesses you give others now, the ones you learned from watching them. That's their love, still moving through the world.", "kind": "ritual"}, {"date": "04-09", "month": "April", "day": 9, "text": "Some days grief will feel like missing a limb. Other days, like a scar you've simply learned to live inside of. Both are still healing, in their own way.", "kind": "reflection"}, {"date": "04-10", "month": "April", "day": 10, "text": "Keep a photo of them somewhere you'll see it often, not out of sadness, but so their face stays part of your ordinary days.", "kind": "ritual"}, {"date": "04-11", "month": "April", "day": 11, "text": "You don't need closure to keep living. Some relationships were never meant to close — just to keep unfolding, differently.", "kind": "reflection"}, {"date": "04-12", "month": "April", "day": 12, "text": "Sit with the guilt if it visits — the \"I should have,\" the \"I wish I'd.\" Then remind yourself: you did the best you could with what you knew then.", "kind": "ritual"}, {"date": "04-13", "month": "April", "day": 13, "text": "Their death didn't erase their life. Every joy, every argument, every ordinary day you shared still happened, and still counts.", "kind": "reflection"}, {"date": "04-14", "month": "April", "day": 14, "text": "You're allowed to feel joy at a celebration without guilt for the empty chair beside you. They'd want you there, fully.", "kind": "reflection"}, {"date": "04-15", "month": "April", "day": 15, "text": "Notice the strength it's taken just to keep functioning some days. That's not nothing. That's a quiet kind of courage.", "kind": "ritual"}, {"date": "04-16", "month": "April", "day": 16, "text": "Some people move through the world differently now because you loved them well enough to be forever changed by losing them.", "kind": "reflection"}, {"date": "04-17", "month": "April", "day": 17, "text": "You can set a place for them at the table in your mind, even if no one else notices. Some rituals are just for you.", "kind": "reflection"}, {"date": "04-18", "month": "April", "day": 18, "text": "Grief isn't a debt to be paid off with enough tears or enough time. It's simply love, still due somewhere.", "kind": "reflection"}, {"date": "04-19", "month": "April", "day": 19, "text": "Whatever this brings, you don't have to carry it alone. Let someone in, even just a little.", "kind": "reflection"}, {"date": "04-20", "month": "April", "day": 20, "text": "If you find a white feather somewhere unexpected, let yourself believe it's them, saying hello.", "kind": "reflection"}, {"date": "04-21", "month": "April", "day": 21, "text": "Grief doesn't need permission to soften for a while, or to sharpen again without warning. Let it move however it needs to.", "kind": "reflection"}, {"date": "04-22", "month": "April", "day": 22, "text": "You don't owe grief a certain face. Some days it's tears, some days it's silence, some days it's simply getting up.", "kind": "reflection"}, {"date": "04-23", "month": "April", "day": 23, "text": "Tell them about your day, the small stuff — what you ate, what made you laugh. The mundane details were never beneath their love.", "kind": "reflection"}, {"date": "04-24", "month": "April", "day": 24, "text": "You're not weak for needing support. Asking for help is its own kind of strength.", "kind": "reflection"}, {"date": "04-25", "month": "April", "day": 25, "text": "Notice a smell that pulls you straight back to them — perfume, coffee, rain. Let it hold you there a moment before you move on.", "kind": "ritual"}, {"date": "04-26", "month": "April", "day": 26, "text": "The love you have for them didn't stop when they died. It just lost its usual place to go.", "kind": "reflection"}, {"date": "04-27", "month": "April", "day": 27, "text": "You're allowed to redecorate, move house, change your routines. Loving them doesn't require freezing your life in place.", "kind": "reflection"}, {"date": "04-28", "month": "April", "day": 28, "text": "Some grief is loud enough to fill a room. Some is small enough to fit in your pocket, carried quietly through an ordinary moment. Both are real.", "kind": "reflection"}, {"date": "04-29", "month": "April", "day": 29, "text": "Look for them in coincidences — a song on the radio, a number that meant something, a stranger with their laugh. Let the world feel a little less random for a moment.", "kind": "ritual"}, {"date": "04-30", "month": "April", "day": 30, "text": "You've made it through every single day since losing them. That's not luck. That's you.", "kind": "reflection"}, {"date": "05-01", "month": "May", "day": 1, "text": "Grief will ask more of you some seasons than others. Be as gentle with yourself as you'd be with someone else carrying this.", "kind": "reflection"}, {"date": "05-02", "month": "May", "day": 2, "text": "Keep their voicemail, their handwriting, their playlist — whatever pieces of them still exist. There's no rush to be ready to let any of it go.", "kind": "ritual"}, {"date": "05-03", "month": "May", "day": 3, "text": "You can hold both the unfairness of losing them and the gratitude for having had them, without one cancelling out the other.", "kind": "reflection"}, {"date": "05-04", "month": "May", "day": 4, "text": "Know this: loving someone enough to still grieve them is never something to apologise for.", "kind": "reflection"}, {"date": "05-05", "month": "May", "day": 5, "text": "Grief may never fully leave, but it does learn to make room for the rest of your life, and the rest of your life learns to make room for it.", "kind": "reflection"}, {"date": "05-06", "month": "May", "day": 6, "text": "Cry if the ache surfaces without warning. Tears aren't proof you're struggling — they're proof you loved deeply enough for this to still move you.", "kind": "reflection"}, {"date": "05-07", "month": "May", "day": 7, "text": "Some days you'll wish you could hear their voice just once more. That longing doesn't fade — it just becomes part of how you love them now.", "kind": "reflection"}, {"date": "05-08", "month": "May", "day": 8, "text": "You are allowed to laugh loudly at a memory of them, even mid-tears. Grief was never meant to be tidy.", "kind": "reflection"}, {"date": "05-09", "month": "May", "day": 9, "text": "Notice how far you've come, even on the days it doesn't feel like it. Survival rarely announces itself loudly.", "kind": "ritual"}, {"date": "05-10", "month": "May", "day": 10, "text": "Keep something small of theirs in your pocket or bag. Let it be a quiet companion through ordinary moments.", "kind": "ritual"}, {"date": "05-11", "month": "May", "day": 11, "text": "You're not required to feel grateful for the lesson grief taught you. Sometimes it's simply allowed to just be loss, nothing redemptive required.", "kind": "reflection"}, {"date": "05-12", "month": "May", "day": 12, "text": "The bond you shared doesn't require their presence to keep growing. Love can still deepen, even from memory.", "kind": "reflection"}, {"date": "05-13", "month": "May", "day": 13, "text": "Notice the ways you've become kinder, gentler, more patient — pieces of them, quietly shaping who you are now.", "kind": "ritual"}, {"date": "05-14", "month": "May", "day": 14, "text": "Some grief softens with time. Some doesn't, and that's not a failure to heal. Grief moves at its own pace, not a schedule.", "kind": "reflection"}, {"date": "05-15", "month": "May", "day": 15, "text": "Say thank you to them, for however long you had, however short it felt. Gratitude and grief can sit side by side.", "kind": "ritual"}, {"date": "05-16", "month": "May", "day": 16, "text": "You are allowed to feel proud of surviving something this hard, without it minimising how hard it still is.", "kind": "reflection"}, {"date": "05-17", "month": "May", "day": 17, "text": "Notice the quiet moments they'd have loved — a sunset, a good meal, a joke only you'd find funny. Let them in on it, wherever they are.", "kind": "ritual"}, {"date": "05-18", "month": "May", "day": 18, "text": "Grief will always be part of your story, but it was never the whole of it. The love came first, and it's still the larger part.", "kind": "reflection"}, {"date": "05-19", "month": "May", "day": 19, "text": "However heavy this feels right now, it has never been the whole truth of who you are. You are still, and will always be, someone capable of deep love.", "kind": "reflection"}, {"date": "05-20", "month": "May", "day": 20, "text": "You don't need a big reason to reach for comfort — a blanket, a candle, a favourite song. Small comforts still count.", "kind": "reflection"}, {"date": "05-21", "month": "May", "day": 21, "text": "Notice the friends who show up without being asked, months or years later. That quiet loyalty deserves to be noticed and thanked.", "kind": "ritual"}, {"date": "05-22", "month": "May", "day": 22, "text": "Grief doesn't erase the plans you once made together. Some of them, you get to keep living out, in their honour.", "kind": "reflection"}, {"date": "05-23", "month": "May", "day": 23, "text": "You are allowed to feel two things at once — peace and heartbreak, relief and longing. Grief was never one feeling wide.", "kind": "reflection"}, {"date": "05-24", "month": "May", "day": 24, "text": "Look at their handwriting or a message they once sent. Let their words reach you again, exactly as they were.", "kind": "ritual"}, {"date": "05-25", "month": "May", "day": 25, "text": "Some days you'll want to talk about them for hours. Other days, not at all. Both are okay, and neither needs explaining.", "kind": "reflection"}, {"date": "05-26", "month": "May", "day": 26, "text": "You are not failing at grief by having good days. Joy returning doesn't mean love leaving.", "kind": "reflection"}, {"date": "05-27", "month": "May", "day": 27, "text": "Notice how your definition of strength has changed since losing them. What once looked like weakness might just be honesty now.", "kind": "ritual"}, {"date": "05-28", "month": "May", "day": 28, "text": "Keep a small object nearby that reminds you of a happy memory with them — not the loss, the joy. Let it live somewhere close.", "kind": "ritual"}, {"date": "05-29", "month": "May", "day": 29, "text": "Grief may reshape your relationships with others too — some grow closer, others fall away. Let that happen without guilt.", "kind": "reflection"}, {"date": "05-30", "month": "May", "day": 30, "text": "You are allowed to feel like yourself again, even while still missing them fiercely. Those two things were never opposites.", "kind": "reflection"}, {"date": "05-31", "month": "May", "day": 31, "text": "Some days you'll wonder what they'd think of who you've become. Trust that the love they had for you hasn't changed.", "kind": "reflection"}, {"date": "06-01", "month": "June", "day": 1, "text": "Grief will ask you to be patient with yourself in ways you've never had to before. Let it teach you that, gently.", "kind": "reflection"}, {"date": "06-02", "month": "June", "day": 2, "text": "Notice the seasons changing and how grief shifts with them — heavier in some, lighter in others. There's no wrong way for it to move.", "kind": "ritual"}, {"date": "06-03", "month": "June", "day": 3, "text": "You're allowed to feel disconnected from people who haven't experienced a loss like this. It doesn't mean you're alone — just differently understood.", "kind": "reflection"}, {"date": "06-04", "month": "June", "day": 4, "text": "Sit somewhere quiet and let yourself simply miss them, without trying to fix the feeling or rush past it.", "kind": "ritual"}, {"date": "06-05", "month": "June", "day": 5, "text": "The love you carry for them has nowhere to go but forward, into how you live, who you help, what you notice in the world now.", "kind": "reflection"}, {"date": "06-06", "month": "June", "day": 6, "text": "You don't have to justify grief resurfacing after what feels like calm. It was never gone — just resting.", "kind": "reflection"}, {"date": "06-07", "month": "June", "day": 7, "text": "Notice the people who ask about them by name, long after the loss. That's a gift — let yourself receive it.", "kind": "ritual"}, {"date": "06-08", "month": "June", "day": 8, "text": "However this feels, you are still, and will always be, worthy of the love you're still carrying for them.", "kind": "reflection"}, {"date": "06-09", "month": "June", "day": 9, "text": "Do something silly. They're probably laughing at you for it, exactly like they always did.", "kind": "ritual"}, {"date": "06-10", "month": "June", "day": 10, "text": "If you forget a special day, you haven't failed them. Life happened around them when they were here too — this is no different.", "kind": "reflection"}, {"date": "06-11", "month": "June", "day": 11, "text": "You are allowed to feel completely fine one moment and undone the next. Grief was never going to move in a straight line.", "kind": "reflection"}, {"date": "06-12", "month": "June", "day": 12, "text": "Notice a stranger's kindness and let it land. Grief can make the world feel harder, but it hasn't stopped being kind too.", "kind": "ritual"}, {"date": "06-13", "month": "June", "day": 13, "text": "Some days, simply getting through is the whole achievement. That's enough. It's always been enough.", "kind": "reflection"}, {"date": "06-14", "month": "June", "day": 14, "text": "You don't owe grief constant attention to prove your love was real. Love was never something that needed proving.", "kind": "reflection"}, {"date": "06-15", "month": "June", "day": 15, "text": "Notice how naturally you've started weaving them into your everyday language — \"they used to say,\" \"they always did.\" That's not stuck in the past. That's them, still present tense in your life.", "kind": "ritual"}, {"date": "06-16", "month": "June", "day": 16, "text": "Let yourself feel light for a while, without checking whether you've earned it. Lightness isn't a betrayal.", "kind": "reflection"}, {"date": "06-17", "month": "June", "day": 17, "text": "You are allowed to talk to them about the big decisions in your life, even now. Their guidance doesn't stop just because they're gone.", "kind": "reflection"}, {"date": "06-18", "month": "June", "day": 18, "text": "Notice the ways loss has softened you toward other people's pain. That's not a burden you carry — that's compassion, born from love.", "kind": "ritual"}, {"date": "06-19", "month": "June", "day": 19, "text": "Some anniversaries you'll brace for, and they'll pass gently. Others sneak up unannounced. There's no controlling which is which.", "kind": "reflection"}, {"date": "06-20", "month": "June", "day": 20, "text": "You're allowed to feel like the unluckiest person in the world some days, and the luckiest for having known them on others.", "kind": "reflection"}, {"date": "06-21", "month": "June", "day": 21, "text": "Keep talking about the hard parts too — the ending, the pain, the mess of it. Grief isn't only the highlight reel.", "kind": "ritual"}, {"date": "06-22", "month": "June", "day": 22, "text": "Notice the quiet strength it takes to keep showing up for other people, even while carrying this. That doesn't go unnoticed, even if it feels invisible.", "kind": "ritual"}, {"date": "06-23", "month": "June", "day": 23, "text": "You are not required to have this figured out. Nobody does. Grief was never a puzzle with a solution.", "kind": "reflection"}, {"date": "06-24", "month": "June", "day": 24, "text": "Let someone take care of you for once, even in a small way. You don't always have to be the one holding everything together.", "kind": "reflection"}, {"date": "06-25", "month": "June", "day": 25, "text": "Notice the moments you feel closest to them — often not the big days, but the small, unexpected ones. Those count just as much.", "kind": "ritual"}, {"date": "06-26", "month": "June", "day": 26, "text": "You are allowed to change how you grieve over time. What helped last year might not help now, and that's not inconsistency — that's growth.", "kind": "reflection"}, {"date": "06-27", "month": "June", "day": 27, "text": "Some days grief will feel like gratitude wearing a heavier coat. Let both feelings exist at once.", "kind": "reflection"}, {"date": "06-28", "month": "June", "day": 28, "text": "However this unfolds, you are still someone capable of love this deep, this lasting. That was never in question.", "kind": "reflection"}, {"date": "06-29", "month": "June", "day": 29, "text": "Notice how much lighter it feels to say their name than to avoid it. Silence was never protecting anyone.", "kind": "ritual"}, {"date": "06-30", "month": "June", "day": 30, "text": "You are allowed to feel nostalgic for a life that no longer exists, while still building the one you're in now.", "kind": "reflection"}, {"date": "07-01", "month": "July", "day": 1, "text": "Some days grief will feel unbearably heavy for no clear reason. You don't need a reason. You're allowed to just feel it.", "kind": "reflection"}, {"date": "07-02", "month": "July", "day": 2, "text": "Notice the small traditions you've kept alive without meaning to — a recipe, a phrase, a Sunday habit. That's them, still woven into your life.", "kind": "ritual"}, {"date": "07-03", "month": "July", "day": 3, "text": "You don't have to protect other people from your grief. Let them see it, if you're able to. Real connection rarely comes from hiding.", "kind": "reflection"}, {"date": "07-04", "month": "July", "day": 4, "text": "Sit with an old memory long enough to really feel it, instead of rushing past it. Some memories deserve to be lingered in.", "kind": "ritual"}, {"date": "07-05", "month": "July", "day": 5, "text": "You are allowed to grieve people who are still alive too — the version of yourself before this loss, the future you imagined together. That grief counts as well.", "kind": "reflection"}, {"date": "07-06", "month": "July", "day": 6, "text": "Notice a small joy and let yourself have it fully, without checking if it's allowed. It is.", "kind": "ritual"}, {"date": "07-07", "month": "July", "day": 7, "text": "Some people will never understand this kind of loss, and that's alright. You don't need everyone to understand it — just the ones who matter.", "kind": "reflection"}, {"date": "07-08", "month": "July", "day": 8, "text": "You don't owe grief performance for other people's comfort. Cry if it comes. Laugh if it comes. Let it be honest.", "kind": "reflection"}, {"date": "07-09", "month": "July", "day": 9, "text": "Notice the resilience in you that grief revealed, not created. It was always there — this just proved it.", "kind": "ritual"}, {"date": "07-10", "month": "July", "day": 10, "text": "You are allowed to feel exhausted by grief, even years later. It's heavy work, whether or not it shows.", "kind": "reflection"}, {"date": "07-11", "month": "July", "day": 11, "text": "Some days, the best thing you can do is simply rest. That's not giving up — that's tending to yourself.", "kind": "reflection"}, {"date": "07-12", "month": "July", "day": 12, "text": "Notice how grief has taught you to hold other people's pain more gently. That's a quiet gift, even if it came from a hard place.", "kind": "ritual"}, {"date": "07-13", "month": "July", "day": 13, "text": "You are allowed to feel unready for a milestone they're missing. Grief doesn't check whether the timing is convenient.", "kind": "reflection"}, {"date": "07-14", "month": "July", "day": 14, "text": "Talk about the funny, embarrassing memories too, not just the tender ones. Laughter belongs in this story as much as tears do.", "kind": "ritual"}, {"date": "07-15", "month": "July", "day": 15, "text": "You are not required to \"find meaning\" in losing them. Sometimes loss is simply loss, and that's allowed to be enough of a truth on its own.", "kind": "reflection"}, {"date": "07-16", "month": "July", "day": 16, "text": "Notice how far you've come from the rawest days. Even if it doesn't feel like healing, it is.", "kind": "ritual"}, {"date": "07-17", "month": "July", "day": 17, "text": "You are allowed to feel unsteady on days that seem like they should be easy. Grief doesn't follow logic.", "kind": "reflection"}, {"date": "07-18", "month": "July", "day": 18, "text": "Remember: the love that built this grief was real, is real, and always will be.", "kind": "reflection"}, {"date": "07-19", "month": "July", "day": 19, "text": "Notice how much of them lives on in the small things you do without thinking. Their fingerprints are everywhere, once you look.", "kind": "ritual"}, {"date": "07-20", "month": "July", "day": 20, "text": "You are allowed to feel like grief has changed you permanently. It has. That's not a loss on top of a loss — it's just what love this size does.", "kind": "reflection"}, {"date": "07-21", "month": "July", "day": 21, "text": "Sit with a memory that used to be too painful to touch, and notice if it's softened even slightly. Healing shows up in small increments.", "kind": "ritual"}, {"date": "07-22", "month": "July", "day": 22, "text": "You don't have to earn rest through suffering first. You're allowed to simply rest.", "kind": "reflection"}, {"date": "07-23", "month": "July", "day": 23, "text": "Notice the ways you protect other people from grief they haven't experienced yet. That instinct, born from pain, is its own kind of love.", "kind": "ritual"}, {"date": "07-24", "month": "July", "day": 24, "text": "Some days you'll feel like you're grieving a stranger — the parts of them you never got to fully know. That's allowed too.", "kind": "reflection"}, {"date": "07-25", "month": "July", "day": 25, "text": "You are not responsible for other people's discomfort with your grief. Their unease is theirs to sit with, not yours to manage.", "kind": "reflection"}, {"date": "07-26", "month": "July", "day": 26, "text": "Notice how the ache has changed shape over time — less sharp, perhaps, but no less real. Grief evolves. It doesn't disappear.", "kind": "ritual"}, {"date": "07-27", "month": "July", "day": 27, "text": "Let yourself imagine a conversation with them about something happening in your life right now. Their voice in your head still counts as their presence.", "kind": "reflection"}, {"date": "07-28", "month": "July", "day": 28, "text": "You are allowed to feel like no one truly gets it. And still, let people try. Connection doesn't require perfect understanding.", "kind": "reflection"}, {"date": "07-29", "month": "July", "day": 29, "text": "Notice a piece of music that once felt unbearable and see if it feels different now. Grief reshapes even the hardest triggers, given time.", "kind": "ritual"}, {"date": "07-30", "month": "July", "day": 30, "text": "You don't have to justify to anyone why this loss still affects you. Some loves don't come with an expiry date on the pain.", "kind": "reflection"}, {"date": "07-31", "month": "July", "day": 31, "text": "Some days you'll feel strong enough to help others through their grief. Let that be part of how you carry this too, when you're ready.", "kind": "reflection"}, {"date": "08-01", "month": "August", "day": 1, "text": "Notice the quiet gratitude underneath the grief — for having known them, for having been loved by them. It's there, even on hard days.", "kind": "ritual"}, {"date": "08-02", "month": "August", "day": 2, "text": "You are allowed to feel both broken and whole at once. Grief rarely respects such tidy categories.", "kind": "reflection"}, {"date": "08-03", "month": "August", "day": 3, "text": "Sit outside for a while and let the world simply exist around you. You don't have to do anything with the moment except be in it.", "kind": "ritual"}, {"date": "08-04", "month": "August", "day": 4, "text": "Notice how your capacity for empathy has grown since losing them. That's not a silver lining you owe anyone — it's just true.", "kind": "ritual"}, {"date": "08-05", "month": "August", "day": 5, "text": "You are allowed to feel proud of the person you've become through this, without ever being grateful for the loss itself.", "kind": "reflection"}, {"date": "08-06", "month": "August", "day": 6, "text": "Some grief will always be tender to the touch, no matter how much time passes. That tenderness is proof of how deeply they mattered.", "kind": "reflection"}, {"date": "08-07", "month": "August", "day": 7, "text": "Notice one thing you're looking forward to, however small. Grief and hope were never mutually exclusive.", "kind": "ritual"}, {"date": "08-08", "month": "August", "day": 8, "text": "Notice a piece of clothing or object you've kept simply because it still smells like them, or used to. Let that be reason enough to keep it.", "kind": "ritual"}, {"date": "08-09", "month": "August", "day": 9, "text": "You are allowed to feel a strange kind of peace some days, like grief has finally found a place to rest for a while.", "kind": "reflection"}, {"date": "08-10", "month": "August", "day": 10, "text": "Sit with the thought that no one else will ever love them exactly the way you did. That specific bond was only ever yours to carry.", "kind": "ritual"}, {"date": "08-11", "month": "August", "day": 11, "text": "You don't have to keep proving your grief is real to people who question how long it's lasted. Their doubt says nothing about the truth of it.", "kind": "reflection"}, {"date": "08-12", "month": "August", "day": 12, "text": "Notice how certain birthdays or milestones hit differently than expected — sometimes harder, sometimes gentler. Let the day be whatever it turns out to be.", "kind": "ritual"}, {"date": "08-13", "month": "August", "day": 13, "text": "Talk to them about a mistake you're forgiving yourself for. Imagine their reassurance, and let yourself actually receive it.", "kind": "ritual"}, {"date": "08-14", "month": "August", "day": 14, "text": "Sit for a moment with how much time has passed since you lost them. It isn't fair that the world kept counting the days. But it did. And somehow, so did you.", "kind": "ritual"}, {"date": "08-15", "month": "August", "day": 15, "text": "Notice a stranger who reminds you of them, even faintly. Let that flicker of familiarity feel like a small gift, not a cruel trick.", "kind": "ritual"}, {"date": "08-16", "month": "August", "day": 16, "text": "You are allowed to feel both nostalgic for who you were with them, and curious about who you're becoming without them physically here.", "kind": "reflection"}, {"date": "08-17", "month": "August", "day": 17, "text": "Notice the specific things you'd want to tell them about your week. Say them anyway, even if only in your head.", "kind": "ritual"}, {"date": "08-18", "month": "August", "day": 18, "text": "You don't have to have your grief \"figured out\" by any particular age or year. There is no correct pace.", "kind": "reflection"}, {"date": "08-19", "month": "August", "day": 19, "text": "Sit with an old birthday card or letter from them, if you have one. Let their handwriting feel like a small visit.", "kind": "ritual"}, {"date": "08-20", "month": "August", "day": 20, "text": "You are allowed to feel closer to strangers who've also lost someone, a quiet kinship that doesn't need explaining.", "kind": "reflection"}, {"date": "08-21", "month": "August", "day": 21, "text": "Notice the ways certain foods or meals still carry their memory. Let a shared meal be a small act of connection, even now.", "kind": "ritual"}, {"date": "08-22", "month": "August", "day": 22, "text": "You don't owe grief drama to be taken seriously. Quiet grief is still grief, fully valid.", "kind": "reflection"}, {"date": "08-23", "month": "August", "day": 23, "text": "Talk to them about a fear you haven't told anyone else. Let that honesty exist somewhere, even imagined.", "kind": "ritual"}, {"date": "08-24", "month": "August", "day": 24, "text": "Notice how differently grief shows up depending on who's around you. Let yourself be exactly as open or guarded as each moment calls for.", "kind": "ritual"}, {"date": "08-25", "month": "August", "day": 25, "text": "You are allowed to feel disbelief, even now, that this is truly your life. Some losses never stop feeling slightly unreal.", "kind": "reflection"}, {"date": "08-26", "month": "August", "day": 26, "text": "Sit with the specific things you miss most — not the big abstract loss, but a laugh, a smell, a particular Tuesday. The specifics are where the love lives.", "kind": "ritual"}, {"date": "08-27", "month": "August", "day": 27, "text": "Notice how your grief has taught people around you how to show up for pain better. That ripple effect is part of their legacy too.", "kind": "ritual"}, {"date": "08-28", "month": "August", "day": 28, "text": "You are allowed to grieve out of order — missing a moment from years ago just as sharply as something recent. Time doesn't file grief chronologically.", "kind": "reflection"}, {"date": "08-29", "month": "August", "day": 29, "text": "You don't have to carry every memory perfectly. Some will blur with time, and that's not losing them — it's just being human.", "kind": "reflection"}, {"date": "08-30", "month": "August", "day": 30, "text": "Notice the version of yourself that exists only because you loved them. That version is permanent, regardless of what fades.", "kind": "ritual"}, {"date": "08-31", "month": "August", "day": 31, "text": "You are allowed to feel like the world owes you an explanation it will never give. That anger is valid, even without an answer.", "kind": "reflection"}, {"date": "09-01", "month": "September", "day": 1, "text": "Sit with a photo of them and simply look, without needing to feel any particular way about it. Presence is enough.", "kind": "ritual"}, {"date": "09-02", "month": "September", "day": 2, "text": "Notice the friends who've stayed steady through all of this. Let yourself lean on them, even now.", "kind": "ritual"}, {"date": "09-03", "month": "September", "day": 3, "text": "You are allowed to feel disoriented by how normal the world looks, when everything in you has changed. That disconnect is real, and it's okay.", "kind": "reflection"}, {"date": "09-04", "month": "September", "day": 4, "text": "Let yourself say \"I miss you\" out loud, wherever you are. Some words need to be spoken, not just felt.", "kind": "ritual"}, {"date": "09-05", "month": "September", "day": 5, "text": "Notice the resilience you didn't know you had until you needed it. That strength is yours now, permanently.", "kind": "ritual"}, {"date": "09-06", "month": "September", "day": 6, "text": "You don't have to resolve every complicated feeling about them. Love can hold contradictions and still be whole.", "kind": "reflection"}, {"date": "09-07", "month": "September", "day": 7, "text": "Sit quietly and let a memory come to you, uninvited. Don't chase it away — let it visit as long as it needs to.", "kind": "ritual"}, {"date": "09-08", "month": "September", "day": 8, "text": "You are allowed to feel disloyal for moving forward, even though you know, somewhere, that you're not. Guilt doesn't always listen to logic.", "kind": "reflection"}, {"date": "09-09", "month": "September", "day": 9, "text": "Notice the ways this loss has made you more present with the people still here. That awareness is a quiet form of honouring them.", "kind": "ritual"}, {"date": "09-10", "month": "September", "day": 10, "text": "You don't have to keep grief hidden to seem \"fine\" to others. Let it show, if that's what today needs.", "kind": "reflection"}, {"date": "09-11", "month": "September", "day": 11, "text": "Some grief will resurface around big life events — weddings, births, new jobs. Let it be part of the celebration, not separate from it.", "kind": "reflection"}, {"date": "09-12", "month": "September", "day": 12, "text": "You are allowed to talk to them about your fears. Their absence doesn't mean their support has to disappear too.", "kind": "reflection"}, {"date": "09-13", "month": "September", "day": 13, "text": "Notice a piece of advice they once gave you, and let it guide you again, exactly as it would have.", "kind": "ritual"}, {"date": "09-14", "month": "September", "day": 14, "text": "You don't have to make peace with losing them to keep living well. Some things you carry unresolved, and that's alright.", "kind": "reflection"}, {"date": "09-15", "month": "September", "day": 15, "text": "Sit with the parts of grief that still feel raw, without rushing to soothe them. Some pain just needs witnessing.", "kind": "ritual"}, {"date": "09-16", "month": "September", "day": 16, "text": "You are allowed to feel both shaped and unshaken by this loss — changed, but still fundamentally you.", "kind": "reflection"}, {"date": "09-17", "month": "September", "day": 17, "text": "Notice the quiet moments when grief feels almost peaceful, like sitting beside an old friend rather than fighting a storm.", "kind": "ritual"}, {"date": "09-18", "month": "September", "day": 18, "text": "You are allowed to feel unready for how normal life demands you to be, even now. Readiness was never required.", "kind": "reflection"}, {"date": "09-19", "month": "September", "day": 19, "text": "Sit with the thought that they'd be proud of you, even for the smallest things. Let that thought stay a while.", "kind": "ritual"}, {"date": "09-20", "month": "September", "day": 20, "text": "You don't need permission to grieve differently than everyone else in your life. This is yours to carry your own way.", "kind": "reflection"}, {"date": "09-21", "month": "September", "day": 21, "text": "Notice how certain places still hold their presence — a room, a street, a chair. Let those spaces stay sacred, if you need them to.", "kind": "ritual"}, {"date": "09-22", "month": "September", "day": 22, "text": "You are allowed to feel disconnected from your own body some days, like grief lives somewhere deeper than words reach. That's real too.", "kind": "reflection"}, {"date": "09-23", "month": "September", "day": 23, "text": "Talk to them about something ordinary — the weather, a TV show, nothing important. Ordinary conversations still count as connection.", "kind": "ritual"}, {"date": "09-24", "month": "September", "day": 24, "text": "Notice a stranger's small act of kindness and let it soften something in you, even briefly.", "kind": "ritual"}, {"date": "09-25", "month": "September", "day": 25, "text": "You are allowed to want to talk about them constantly with some people, and never with others. Both are honest.", "kind": "reflection"}, {"date": "09-26", "month": "September", "day": 26, "text": "Sit with the thought that you're doing better than you give yourself credit for. However quietly, you are.", "kind": "ritual"}, {"date": "09-27", "month": "September", "day": 27, "text": "Notice how your priorities have shifted since losing them — what matters more now, what matters less. That clarity is a strange gift from a hard place.", "kind": "ritual"}, {"date": "09-28", "month": "September", "day": 28, "text": "You are allowed to feel unfinished with your grief, even years from now. Some love doesn't get a tidy ending.", "kind": "reflection"}, {"date": "09-29", "month": "September", "day": 29, "text": "Sit somewhere that holds a memory of them and simply breathe there for a moment. No agenda, just presence.", "kind": "ritual"}, {"date": "09-30", "month": "September", "day": 30, "text": "Notice how loving them has made you a safer, softer place for other people's pain. That's their legacy, living through you.", "kind": "ritual"}, {"date": "10-01", "month": "October", "day": 1, "text": "You are allowed to feel the seasons differently now — a certain light, a certain chill, pulling grief closer to the surface.", "kind": "reflection"}, {"date": "10-02", "month": "October", "day": 2, "text": "Notice a small thing you do purely because they taught you to. Let that habit feel like a thread still connecting you.", "kind": "ritual"}, {"date": "10-03", "month": "October", "day": 3, "text": "Sit with the reality that grief will always be part of loving someone this deeply. It was never a flaw in the love — it's proof of it.", "kind": "ritual"}, {"date": "10-04", "month": "October", "day": 4, "text": "You are allowed to feel both nostalgic and grateful for change, all at once. Life doesn't ask you to pick a single feeling.", "kind": "reflection"}, {"date": "10-05", "month": "October", "day": 5, "text": "Notice the ways you comfort others now, drawing from what you wish someone had said to you. That's turning pain into purpose, quietly.", "kind": "ritual"}, {"date": "10-06", "month": "October", "day": 6, "text": "Talk to them about a decision you're wrestling with. Their perspective, however imagined now, still matters.", "kind": "ritual"}, {"date": "10-07", "month": "October", "day": 7, "text": "You are allowed to feel closer to them in nature — a certain tree, a certain view. Let those places hold your memory of them gently.", "kind": "reflection"}, {"date": "10-08", "month": "October", "day": 8, "text": "Notice how far your capacity to hold pain has grown, without it hardening you completely. That balance is hard-won.", "kind": "ritual"}, {"date": "10-09", "month": "October", "day": 9, "text": "Sit with an old voicemail, letter, or message if you have one. Let their words reach you again, unchanged by time.", "kind": "ritual"}, {"date": "10-10", "month": "October", "day": 10, "text": "You are allowed to feel like an entirely different person than before this loss. In many ways, you are — and that's not a tragedy, just a truth.", "kind": "reflection"}, {"date": "10-11", "month": "October", "day": 11, "text": "Notice the quiet comfort of routines they were once part of — a certain meal, a certain drive. Let them stay, or let them go, whichever helps.", "kind": "ritual"}, {"date": "10-12", "month": "October", "day": 12, "text": "You are allowed to feel joy without checking whether enough time has passed to earn it. There was never a required waiting period.", "kind": "reflection"}, {"date": "10-13", "month": "October", "day": 13, "text": "Sit with the thought that grief is simply love that has nowhere left to be delivered in person. It still counts as love, fully.", "kind": "ritual"}, {"date": "10-14", "month": "October", "day": 14, "text": "Notice how your instincts to protect and care for others has changed since this loss. That tenderness came from somewhere real.", "kind": "ritual"}, {"date": "10-15", "month": "October", "day": 15, "text": "You are allowed to feel the ache sharpen unexpectedly, even on an ordinary afternoon. It doesn't need a trigger to be valid.", "kind": "reflection"}, {"date": "10-16", "month": "October", "day": 16, "text": "Talk about them to someone new in your life. Let them become part of the story you tell about yourself, not a chapter you skip.", "kind": "ritual"}, {"date": "10-17", "month": "October", "day": 17, "text": "Notice a piece of wisdom they gave you that still holds true. Let it guide you again, exactly as it did before.", "kind": "ritual"}, {"date": "10-18", "month": "October", "day": 18, "text": "You are allowed to feel like no achievement is complete without them there to share it. That instinct to include them never really goes away.", "kind": "reflection"}, {"date": "10-19", "month": "October", "day": 19, "text": "Sit with a small object of theirs and simply hold it. You don't need a reason beyond wanting to feel close.", "kind": "ritual"}, {"date": "10-20", "month": "October", "day": 20, "text": "You are allowed to grieve the future you imagined together, not just the past you shared. That loss counts too.", "kind": "reflection"}, {"date": "10-21", "month": "October", "day": 21, "text": "Notice the strength in the people who've supported you through this. Let yourself feel less alone in it, even for a moment.", "kind": "ritual"}, {"date": "10-22", "month": "October", "day": 22, "text": "Talk to them about how proud you are of surviving this. It's a conversation worth having, even one-sided.", "kind": "ritual"}, {"date": "10-23", "month": "October", "day": 23, "text": "You are allowed to feel unready for the day this stops feeling so raw. Healing doesn't require you to want it on schedule.", "kind": "reflection"}, {"date": "10-24", "month": "October", "day": 24, "text": "Notice how certain smells, sounds, or seasons still pull you straight back to them. Let those sensory threads stay, uninterrupted.", "kind": "ritual"}, {"date": "10-25", "month": "October", "day": 25, "text": "Sit with the knowledge that some people carry losses far heavier, and some far lighter — and neither comparison makes your grief less real.", "kind": "ritual"}, {"date": "10-26", "month": "October", "day": 26, "text": "You are allowed to want to protect their memory fiercely, even from people who mean well but get it wrong.", "kind": "reflection"}, {"date": "10-27", "month": "October", "day": 27, "text": "Notice the ways you've learned to sit with discomfort instead of running from it. That's grief's strange, quiet teaching.", "kind": "ritual"}, {"date": "10-28", "month": "October", "day": 28, "text": "Talk to someone today about a happy memory of them, not the hard parts. Let the joy get equal airtime.", "kind": "ritual"}, {"date": "10-29", "month": "October", "day": 29, "text": "You are allowed to feel the weight of \"firsts\" long after they've technically passed — the first everything without them never really stops echoing.", "kind": "reflection"}, {"date": "10-30", "month": "October", "day": 30, "text": "Sit with gratitude for anyone who has never once made you feel like you needed to \"get over\" this.", "kind": "ritual"}, {"date": "10-31", "month": "October", "day": 31, "text": "Notice how loving them shaped the person you are now, in ways that will outlast this grief entirely.", "kind": "ritual"}, {"date": "11-01", "month": "November", "day": 1, "text": "You are allowed to feel closer to them during quiet, reflective months. Let the season hold space for both of you.", "kind": "reflection"}, {"date": "11-02", "month": "November", "day": 2, "text": "Notice a tradition you might want to start in their memory. It doesn't need to be big to matter.", "kind": "ritual"}, {"date": "11-03", "month": "November", "day": 3, "text": "Sit with the thought that their impact on the world didn't end when they did. It continues, through you and everyone else they touched.", "kind": "ritual"}, {"date": "11-04", "month": "November", "day": 4, "text": "You are allowed to feel behind in life because of this loss. Grief doesn't care about timelines other people expect.", "kind": "reflection"}, {"date": "11-05", "month": "November", "day": 5, "text": "Talk to them about something you're proud of. Let their imagined pride feel as real as it would have been.", "kind": "ritual"}, {"date": "11-06", "month": "November", "day": 6, "text": "Notice how you've learned to hold space for other people's grief differently now. That empathy came at a real cost, and it's still a gift.", "kind": "ritual"}, {"date": "11-07", "month": "November", "day": 7, "text": "You are allowed to feel a fresh wave of sadness even after long stretches of calm. Grief was never promised to be linear.", "kind": "reflection"}, {"date": "11-08", "month": "November", "day": 8, "text": "Sit somewhere cozy and let yourself simply exist without needing to process anything. Rest doesn't require productivity.", "kind": "ritual"}, {"date": "11-09", "month": "November", "day": 9, "text": "Notice the ways you've become someone others turn to in hard times. That capacity grew from your own hardest time.", "kind": "ritual"}, {"date": "11-10", "month": "November", "day": 10, "text": "You are allowed to feel like this loss reshaped your entire sense of what matters. That recalibration is real, and it's allowed to stay.", "kind": "reflection"}, {"date": "11-11", "month": "November", "day": 11, "text": "Talk to them about the people in your life now, the ones they never got to meet. Let them exist in that story too.", "kind": "ritual"}, {"date": "11-12", "month": "November", "day": 12, "text": "Notice the quiet comfort of simply thinking their name, without needing to say it out loud. Some love lives best in silence.", "kind": "ritual"}, {"date": "11-13", "month": "November", "day": 13, "text": "You are allowed to feel both older and more tender since this loss, aged by grief but softened by it too.", "kind": "reflection"}, {"date": "11-14", "month": "November", "day": 14, "text": "Sit with the fact that you've carried this for a long time now, and you're still here. That's not small.", "kind": "ritual"}, {"date": "11-15", "month": "November", "day": 15, "text": "Notice a small joy today that you wouldn't have noticed before losing them. Grief sometimes sharpens gratitude in strange, unwanted ways.", "kind": "ritual"}, {"date": "11-16", "month": "November", "day": 16, "text": "You are allowed to feel disoriented by how much life has changed since they've been gone. Let that disorientation exist without needing to solve it.", "kind": "reflection"}, {"date": "11-17", "month": "November", "day": 17, "text": "Talk to someone about what you wish you'd said to them, if there's still something unsaid. It's never too late to say it out loud.", "kind": "ritual"}, {"date": "11-18", "month": "November", "day": 18, "text": "Notice how your relationship with them continues, even now — through memory, through habit, through love that never needed their presence to keep existing.", "kind": "ritual"}, {"date": "11-19", "month": "November", "day": 19, "text": "You are allowed to feel closer to understanding your own mortality since this loss. That awareness, however heavy, often deepens how you live.", "kind": "reflection"}, {"date": "11-20", "month": "November", "day": 20, "text": "Sit with the thought that grief is proof you loved well. Not everyone gets to carry something this real.", "kind": "ritual"}, {"date": "11-21", "month": "November", "day": 21, "text": "Notice the small mercies in how they lived, or how they left. Even in loss, there can be things to be grateful for.", "kind": "ritual"}, {"date": "11-22", "month": "November", "day": 22, "text": "You are allowed to feel like the hardest part of missing them is not being able to share your life with them anymore. That specific ache deserves its own space.", "kind": "reflection"}, {"date": "11-23", "month": "November", "day": 23, "text": "Talk to them about gratitude — for the years you had, however many or few. Let thankfulness sit beside the grief.", "kind": "ritual"}, {"date": "11-24", "month": "November", "day": 24, "text": "Notice how differently you show up for people now, more patient, more present. That's them, quietly still teaching you.", "kind": "ritual"}, {"date": "11-25", "month": "November", "day": 25, "text": "You are allowed to feel like grief has no finish line, and to stop looking for one. This is simply part of how you'll love them, always.", "kind": "reflection"}, {"date": "11-26", "month": "November", "day": 26, "text": "Sit with a moment of pure fondness for them today, no ache required, just warmth.", "kind": "ritual"}, {"date": "11-27", "month": "November", "day": 27, "text": "Notice the ways you've grown braver since this loss, willing to feel things fully instead of avoiding them.", "kind": "ritual"}, {"date": "11-28", "month": "November", "day": 28, "text": "You are allowed to feel a complicated mix of gratitude and grief around gatherings that highlight their absence. Both are true at once.", "kind": "reflection"}, {"date": "11-29", "month": "November", "day": 29, "text": "Talk to them about the small wins — the things too minor to tell anyone else. They were never too small for their attention.", "kind": "ritual"}, {"date": "11-30", "month": "November", "day": 30, "text": "Notice how far you've come since the earliest, rawest days. Even without feeling \"healed,\" you are undeniably further along.", "kind": "ritual"}, {"date": "12-01", "month": "December", "day": 1, "text": "You are allowed to feel the weight of the year closing in, another year lived without them physically here. That weight is valid.", "kind": "reflection"}, {"date": "12-02", "month": "December", "day": 2, "text": "Sit with the thought that time passing doesn't mean love fading. The two were never actually connected.", "kind": "ritual"}, {"date": "12-03", "month": "December", "day": 3, "text": "Notice a quiet act of remembrance you can do simply for yourself, with no audience. Some grief rituals are only ever meant to be private.", "kind": "ritual"}, {"date": "12-04", "month": "December", "day": 4, "text": "You are allowed to feel both exhausted and resilient by how long you've carried this. Both truths can coexist.", "kind": "reflection"}, {"date": "12-05", "month": "December", "day": 5, "text": "Talk to someone about how they're really doing with their own grief, if you know someone else who's lost someone. Shared understanding is its own comfort.", "kind": "ritual"}, {"date": "12-06", "month": "December", "day": 6, "text": "Notice how certain colours, songs, or scents of this season pull memories closer. Let them, even if it aches.", "kind": "ritual"}, {"date": "12-07", "month": "December", "day": 7, "text": "You are allowed to feel proud of how you've learned to live alongside this loss, rather than around it.", "kind": "reflection"}, {"date": "12-08", "month": "December", "day": 8, "text": "Sit with the thought that this grief, however heavy, has never once stopped you from being capable of love — for others, and for yourself.", "kind": "ritual"}, {"date": "12-09", "month": "December", "day": 9, "text": "Notice the parts of your personality that were shaped by them — a sense of humour, a way of caring, a way of seeing the world. Let that inheritance feel like comfort.", "kind": "ritual"}, {"date": "12-10", "month": "December", "day": 10, "text": "You are allowed to feel closer to them in dreams, in quiet moments, in the space just before sleep. Those moments count as real connection.", "kind": "reflection"}, {"date": "12-11", "month": "December", "day": 11, "text": "Talk to them about how the year has gone. Let it be an honest update, the good and the hard both.", "kind": "ritual"}, {"date": "12-12", "month": "December", "day": 12, "text": "Notice how you've learned to hold joy and grief in the same hand, without needing to put one down to hold the other.", "kind": "ritual"}, {"date": "12-13", "month": "December", "day": 13, "text": "You are allowed to feel like this loss will always be part of how you experience this time of year. That doesn't mean it has to define it entirely.", "kind": "reflection"}, {"date": "12-14", "month": "December", "day": 14, "text": "Sit with a memory of them laughing, and let yourself smile at it fully, without guilt.", "kind": "ritual"}, {"date": "12-15", "month": "December", "day": 15, "text": "Notice how the people who loved them still carry pieces of them too. You are not alone in keeping their memory alive.", "kind": "ritual"}, {"date": "12-16", "month": "December", "day": 16, "text": "You are allowed to feel unready for gatherings that highlight their absence. Prepare yourself gently, and give yourself permission to leave early if you need to.", "kind": "reflection"}, {"date": "12-17", "month": "December", "day": 17, "text": "Talk to yourself the way you'd talk to a friend carrying this same grief — with patience, not judgment.", "kind": "ritual"}, {"date": "12-18", "month": "December", "day": 18, "text": "Notice the resilience it's taken just to keep choosing to live fully, even with this loss woven through everything. That choice, repeated daily, is its own quiet triumph.", "kind": "ritual"}, {"date": "12-19", "month": "December", "day": 19, "text": "You are allowed to feel closer to your own vulnerability since losing them. That openness, however uncomfortable, often deepens your other relationships too.", "kind": "reflection"}, {"date": "12-20", "month": "December", "day": 20, "text": "Sit with gratitude for every ordinary day you shared with them, the ones that felt unremarkable at the time and precious now.", "kind": "ritual"}, {"date": "12-21", "month": "December", "day": 21, "text": "Notice how the shortest, darkest days of the year sometimes mirror how grief can feel — heavy, but never permanent. Light returns, even here.", "kind": "ritual"}, {"date": "12-22", "month": "December", "day": 22, "text": "You are allowed to create new traditions this year, ones that honour them without needing to replicate exactly what came before.", "kind": "reflection"}, {"date": "12-23", "month": "December", "day": 23, "text": "Talk to them about hope — for the year ahead, for the people you love, for yourself. Let hope and grief share the same breath.", "kind": "ritual"}, {"date": "12-24", "month": "December", "day": 24, "text": "Notice a quiet moment amid the busyness to simply think of them, undisturbed. That pause is a form of honouring them.", "kind": "ritual"}, {"date": "12-25", "month": "December", "day": 25, "text": "You are allowed to feel their absence more sharply during moments meant for togetherness. That ache is proof of how much they belonged in these moments.", "kind": "reflection"}, {"date": "12-26", "month": "December", "day": 26, "text": "Sit with the thought that surviving another year of missing them is its own kind of strength, however unnoticed.", "kind": "ritual"}, {"date": "12-27", "month": "December", "day": 27, "text": "Notice how loving them continues to shape the choices you make, the person you're becoming, long after they're gone.", "kind": "ritual"}, {"date": "12-28", "month": "December", "day": 28, "text": "You are allowed to feel reflective about how far you've come this year, in grief and in life both.", "kind": "reflection"}, {"date": "12-29", "month": "December", "day": 29, "text": "Talk to them about what you're hoping for in the year ahead. Let their imagined encouragement carry you into it.", "kind": "ritual"}, {"date": "12-30", "month": "December", "day": 30, "text": "Notice how much love it takes to still be grieving this deeply, this long. That's never something to apologise for.", "kind": "ritual"}, {"date": "12-31", "month": "December", "day": 31, "text": "Whatever this year has held, you carried it — grief, love, and everything in between. That's not nothing. That's everything.", "kind": "reflection"}];
